import json, itertools
from decimal import Decimal
from urban_micro import frontier_mix_rank_report as fmr

def make_frontier(points):
    pts = []
    for b,c,e,l,u,pick,sw in points:
        panels = [
            '{"by":"region","key":"r1","n":1,"effect":1.000000,"lower":0.000000,"upper":2.000000}',
            '{"by":"window","key":"w1","n":1,"effect":2.000000,"lower":1.000000,"upper":3.000000}',
        ]
        pts.append(
            '{"budget":%.6f,"cost":%.6f,"effect":%.6f,"lower":%.6f,"upper":%.6f,"pick":%s,"switch":%s,"panels":[%s]}'
            % (b,c,e,l,u,json.dumps(pick,separators=(",",":")), "true" if sw else "false", ",".join(panels))
        )
    return '{"points":['+",".join(pts)+']}\n'

f1 = make_frontier([(10,10,1.000000,0.5,1.5,["green"],False),(20,10,2.000000,1,3,["green"],False)])
f2 = make_frontier([(10,10,1.500000,0.5,2.5,["green"],False),(20,10,0.500000,0.1,0.9,["roof"],True)])
f3 = make_frontier([(10,10,3.000000,2,4,["roof"],False),(20,10,3.000000,2,4,["material"],True)])
f4 = make_frontier([(10,0,0.000000,0,0,[],False),(20,0,0.000000,0,0,[],False)])
frontiers = {"s1":f1,"s2":f2,"s3":f3,"s4":f4}
weights = {"s1":1,"s2":2,"s3":3,"s4":4}
data = json.loads(fmr(frontiers, weights))

for pi, point in enumerate(data["points"]):
    groups = {}
    for sk in ["s1","s2","s3","s4"]:
        d = json.loads(frontiers[sk][:-1])["points"][pi]
        groups.setdefault(tuple(d["pick"]), []).append(
            (Decimal(str(weights[sk])), Decimal(str(d["effect"]))))
    for t in point["tests"]:
        a, b = tuple(t["a"]), tuple(t["b"])
        ga, gb = groups[a], groups[b]
        pooled = ga+gb; na=len(ga)
        obs = sum(w*e for w,e in ga)/sum(w for w,e in ga) - sum(w*e for w,e in gb)/sum(w for w,e in gb)
        hits=0; total=0
        for combo in itertools.combinations(range(len(pooled)), na):
            A=[pooled[i] for i in combo]; B=[pooled[i] for i in range(len(pooled)) if i not in combo]
            da=sum(w*e for w,e in A)/sum(w for w,e in A)-sum(w*e for w,e in B)/sum(w for w,e in B)
            total+=1
            if abs(da)>=abs(obs): hits+=1
        assert abs(t["p"]-hits/total)<5e-7, (t["p"],hits,total)
        assert abs(t["diff"]-float(obs))<5e-7
        assert t["n_a"]==na and t["n_b"]==len(gb)
print("all exact p-values match brute force")

fs = {"a1": make_frontier([(10,10,2.0,1,3,["green"],False)]),
      "a2": make_frontier([(10,10,2.0,1,3,["green"],False)]),
      "b1": make_frontier([(10,10,5.0,4,6,["roof"],False)])}
ws = {"a1":11,"a2":11,"b1":10}
d = json.loads(fmr(fs, ws))
r0 = d["points"][0]["ranks"]
assert [r["pick"] for r in r0] == [["green"],["roof"]]
assert r0[0]["stable"] is True and r0[1]["stable"] is False
print("stability logic OK")

alltests = [t for p in data["points"] for t in p["tests"]]
ps = sorted(t["p"] for t in alltests); N=len(alltests)
for t in alltests:
    j = sum(1 for x in ps if x < t["p"] or (x==t["p"] and True))
    j = ps.index(t["p"])  # sorted position first occurrence; BH uses rank ties by keys
# exact: recompute q per record ordering (p,budget,a,b)
recs=[]
for pi,p in enumerate(data["points"]):
    for t in p["tests"]:
        recs.append((t["p"],pi,tuple(t["a"]),tuple(t["b"]),t))
recs.sort(key=lambda r:(r[0],r[1],r[2],r[3]))
run=1.0
qmap={}
for j in range(N,0,-1):
    run=min(run,N*recs[j-1][0]/j)
    qmap[id(recs[j-1][4])]=run
for *_,t in recs:
    assert abs(t["q"]-min(1,qmap[id(t)]))<5e-7
out1 = json.loads(fmr(frontiers, weights, alpha=1))
assert all(t["reject"] for p in out1["points"] for t in p["tests"])
print("BH OK")

for bad in [0,-0.01,1.01,True,"0.05",float("nan"),float("inf")]:
    try:
        fmr(frontiers,weights,alpha=bad); raise SystemExit(f"no raise {bad!r}")
    except ValueError: pass
json.loads(fmr(frontiers,weights,alpha=1))
try:
    fmr([], {})
    raise SystemExit("no TypeError")
except TypeError: pass

fs2={f"s{i}": make_frontier([(10,10,float(i+1),0,20,["green"] if i<9 else ["roof"],False)]) for i in range(18)}
ws2={f"s{i}":1 for i in range(18)}
try:
    fmr(fs2,ws2); raise SystemExit("should raise")
except ValueError as e: assert "16" in str(e)
fs3={f"s{i}": make_frontier([(10,10,float(i+1),0,20,["green"] if i<8 else ["roof"],False)]) for i in range(16)}
ws3={f"s{i}":1 for i in range(16)}
assert json.loads(fmr(fs3,ws3))["alpha"]==0.05
